@app.cell
def _(averaging, dataset, np, temperature):
    edges = np.array(dataset["edges_A"])
    shell_volume = 4 * np.pi / 3 * np.diff(edges**3)
    record = dataset["curves"][temperature.value]
    rdf = np.array(record["g"] if averaging.value == "Frame average" else record["single_g"])
    # Integrate shell counts: rho * g * shell volume, then cumulative sum.
    shell_counts = dataset["rho_nominal_A3"] * rdf * shell_volume
    coordination = np.cumsum(shell_counts)
    return coordination, edges, rdf, record

@app.cell(hide_code=True)
def _(coordination, edges, np, plt, radius, rdf, temperature):
    fig, axes = plt.subplots(1, 2, figsize=(10, 3.6), layout="constrained")
    axes[0].plot((edges[:-1] + edges[1:]) / 2, rdf, color="#b5473a", lw=2)
    axes[0].set(xlabel="Separation r (Å)", ylabel="Core pair distribution g(r)", xlim=(1.8, 6), ylim=(0, 7.5))
    axes[1].plot(edges[1:], coordination, color="#b5473a", lw=2)
    axes[1].set(xlabel="Outer shell radius (Å)", ylabel="Cumulative neighbours", xlim=(1.8, 6), ylim=(0, 75))
    for _count in [12, 18, 42]:
        axes[1].axhline(_count, color="0.7", linestyle=":", lw=1)
        axes[1].text(5.8, _count + 1, str(_count), ha="right")
    for _axis in axes:
        _axis.axvline(radius.value, color="0.4", linestyle="--")
        _axis.spines[["top", "right"]].set_visible(False)
    fig
    return

@app.cell(hide_code=True)
def _(coordination, edges, mo, np, radius, record):
    _index = max(0, int(np.searchsorted(edges[1:], radius.value, side="right")) - 1)
    mo.md(f"""
    **Within {edges[_index + 1]:.2f} Å: {coordination[_index]:.1f} neighbours per core atom.**

    The ideal FCC first three shell totals are **12 → 18 → 42**.
    A first-shell coordination requires a boundary near the first RDF minimum.
    Moving the boundary into later shells counts those neighbours too.

    **Model and check:** 2,899-atom free Cu particle, nominal radius 20 Å, Mishin potential.
    Reference atoms lie within 10 Å of the centre of mass; shells extend to 6 Å.
    The nominal density normalizes the curve. Multiplying by that density and each
    shell volume recovers the original mean counts. Surface shape and thermal
    expansion limit the accuracy of this density-normalized core estimate.

    Saved times in this window: {", ".join(str(int(t)) for t in record["times_ps"])} ps.
    More frames from a stationary temperature hold would give a better equilibrium average.
    """)
    return

